import{z as B,x as d,o as E,c as p,q as l,j as n,D as e,d as t,s as o,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"微观结构不变量","description":"","frontmatter":{"title":"微观结构不变量","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/microstructure-invariance.md","filePath":"quant/microstructure-invariance.md","lastUpdated":1791063341000}'),A={name:"quant/microstructure-invariance.md"};function c(m,a,u,h,I,b){const i=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=l('<h1 id="微观结构不变量" tabindex="-1">微观结构不变量 <a class="header-anchor" href="#微观结构不变量" aria-label="Permalink to &quot;微观结构不变量&quot;">​</a></h1><div class="epigraph"><p>不同股票的价格、股数、波动看起来天差地别，但用「生意量」重新标度之后，买卖价差、深度和交易频率会落在相近的关系上。不变量是跨资产的缩放律，不是又一个 lambda 估计窗口。</p><footer>—— Kyle and Obizhaeva, Market Microstructure Invariance: Empirical and Theoretical Foundations, Econometrica, 2016</footer></div><p><a href="/quant/vol-liquidity-feedback">波动–流动性反馈</a>描述同一资产上流动性与波动如何互推。缺口是跨资产：为何大盘活跃股与小盘冷清股的微观结构数字，在适当标度后可以比较？Kyle 与 Obizhaeva（2016）提出微观结构不变量：用成交金额与收益波动合成的生意量（business time）来缩放订单大小、到达率与成本。本课写缩放的含义，不重推单期 Kyle \\(\\lambda\\) 的正态公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接比较两只股票的报价价差或「每股冲击」没有单位。一只股价 \\(10\\)、一只 \\(200\\)，tick、手数、波动都不同。不变量猜想：存在一个以「赌的风险转移量」衡量的时钟，在这个时钟上，一次「典型赌注」的成本、大小与频率满足与品种无关的关系。于是执行成本、最优切片、甚至压力期的脆弱性，可以用生意量在品种之间搬运，而不必每只股票估一套结构参数。</p><p><span class="marginnote">直觉类比：把每笔交易想成一局扑克下注，赌注的尺码由风险而不是股数决定。活跃股一天打几千局小注，冷清股一天只打几十局。比较两桌的「每局成本」要在局数（业务时间）上比；用挂钟比，就像说「一天打 5000 局的桌子更吵」——对缩放毫无用处。</span></p><p>这与 Amihud ILLIQ、经验 \\(\\lambda\\) 的截面比较相关，但更强：它给出指数形式的缩放，而不只是「不流动的股票冲击大」。</p><h3 id="生意时间而不是日历时间" tabindex="-1">生意时间而不是日历时间 <a class="header-anchor" href="#生意时间而不是日历时间" aria-label="Permalink to &quot;生意时间而不是日历时间&quot;">​</a></h3><p>活跃股票的一天包含更多独立的微观赌注，冷清股票的一天更短。日历 VR、日历波动因此不可比。事件时间课已经用成交笔数近似交易时钟；不变量用风险转移量，把波动也乘进去：同样一笔成交，在高波动品种上是更大的赌注。</p><p><span class="marginnote">不变量是假设加校准，不是从 Kyle 1985 单期均衡直接推出来的定理。2016 年文章给出理论动机与实证，阅读时把「不变」当成近似缩放，而不是自然常数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记美元成交速度与收益方差，合成业务时间强度 \\(I\\)。订单的「赌注规模」用份额相对 \\(I\\) 的幂来缩放；成本（价差、冲击）随 \\(I\\) 以特定指数下降。实证：在截面上把对数成本、对数尺寸对 \\(\\log I\\) 回归，看斜率是否接近理论指数，残差是否还有行业结构。应用：把一只股票上估的冲击函数，按 \\(I\\) 的比映射到另一只，作为执行先验。</p><p><span class="marginnote">数字实例：理论指数下成本按 \\(I^{-1/3}\\) 缩放。若甲股的生意量 \\(I\\) 是乙股的 8 倍，典型冲击成本约为乙股的一半——因为 \\(8^{1/3}=2\\)。这就是「指数形式缩放」的含义：不用逐股重估结构参数，先验可以按 \\(I\\) 的比值直接搬运。</span></p><p>与宏观形状：不同品种的 \\(q(\\delta)\\) 在 tick 空间里不可比；按不变量标度后的「深度相对典型赌注」才可画在一起。pro-rata 期货与 FIFO 股票仍可能落在不同族——规则是缩放解释不了的残差。</p>',14)),(E(),n(s,null,{default:e(()=>[o(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20Px%5B%22%E4%BB%B7%E6%A0%BC%20%2F%20%E8%82%A1%E6%95%B0%20%2F%20%CF%83%22%5D%20--%3E%20I%5B%22%E7%94%9F%E6%84%8F%E9%87%8F%20I%22%5D%0A%20%20I%20--%3E%20Cost%5B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E5%B0%BA%E5%AF%B8%E7%9A%84%E7%BC%A9%E6%94%BE%22%5D%0A%20%20I%20--%3E%20Clock%5B%22%E4%B8%9A%E5%8A%A1%E6%97%B6%E9%92%9F%E4%B8%8A%E7%9A%84%E5%88%B0%E8%BE%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"经济内容是：做市与知情交易的约束（资本、注意力、被捡）按风险单位计价，而不是按股数计价。Kyle 的 \\(\\lambda\\) 本身有单位；不变量试图给出 \\(\\lambda\\) 如何随品种的 \\(I\\) 变，使「深度」在风险空间可比。压力期 \\(I\\) 跳变（成交金额崩、波动爆）等于业务时钟加速或赌注变大，成本沿缩放律上移——与螺旋同方向，但给出数量级。",-1)),(E(),n(s,null,{default:e(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E6%96%B0%E9%97%BB%E6%88%96%E5%8E%8B%E5%8A%9B%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20VOL%5B%22%E6%B3%A2%E5%8A%A8%20%CF%83%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20SHOCK%20--%3E%20AMT%5B%22%E6%88%90%E4%BA%A4%E9%87%91%E9%A2%9D%E4%B8%8B%E9%99%8D%22%5D%0A%20%20VOL%20--%3E%20I%5B%22%E7%94%9F%E6%84%8F%E9%87%8F%20I%20%E8%B7%B3%E5%8F%98%22%5D%0A%20%20AMT%20--%3E%20I%0A%20%20I%20--%3E%20BT%5B%22%E4%B8%9A%E5%8A%A1%E6%97%B6%E9%92%9F%E5%8A%A0%E9%80%9F%EF%BC%9A%E8%B5%8C%E6%B3%A8%E5%8F%98%E5%A4%A7%E3%80%81%E9%A2%91%E7%8E%87%E5%8F%98%E4%BD%8E%22%5D%0A%20%20BT%20--%3E%20COST%5B%22%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%E6%B2%BF%E7%BC%A9%E6%94%BE%E5%BE%8B%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20COST%20--%3E%20SP%5B%22%E4%BB%B7%E5%B7%AE%E5%8F%98%E5%AE%BD%E3%80%81%E5%88%87%E7%89%87%E5%8F%98%E6%85%A2%EF%BC%8C%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%E8%9E%BA%E6%97%8B%E5%90%8C%E5%90%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>对速度竞赛：期权 \\(s\\) 的美元价值随品种变，竞赛投入应按 \\(I\\) 缩放。在极小的冷清股上，军备竞赛可能根本不值得，HFT 做市也不进入，义务与专家更重要。</p><p><span class="marginnote">常见误区：初学者容易把不变量读成「所有股票的盘口长得一样」。它只说按业务量标度后某些矩近似落在同一关系上；FIFO 与 pro-rata 这类撮合规则、tick 与涨跌停这些制度差异并不被缩放掉，仍留在残差里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指数对样本（美股、是否含 tick 约束、是否含开收盘）敏感。涨跌停、最小价差钉住会打断缩放。加密与外汇的 \\(I\\) 定义（以何货币、何波动）不唯一。把不变量当精确执行公式，会忽略当天的形状波动与新闻。它是先验与截面比较工具，不是替代 Hasbrouck 永久影响的估计。</p><p><span class="marginnote">不要用「不变量」去宣称所有市场微观结构相同。它只说：在业务时钟上，某些矩的缩放可以近似普适；规则与碎片化仍在残差里。</span></p><p>下一课收束速度本身：缩放律告诉你成本的数量级，不告诉你绝对变快与相对延迟哪一个在改质量。政策变量仍是协议如何处理先到者通吃。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kyle–Obizhaeva 不变量用生意量把成本、尺寸、频率跨品种缩放。</li><li>比较微观结构应在业务时钟上，而不是日历或每股上。</li><li>规则、tick、涨跌停是缩放律的残差来源。</li><li>出处：Kyle and Obizhaeva, <em>Econometrica</em>, 2016。</li></ul>',8))])}const _=B(A,[["render",c]]);export{C as __pageData,_ as default};
